-- Period study v2; read-only; 2026-09-05 through 2026-09-11 Asia/Shanghai.
-- Observation frame uses ended lessons in the available daily partitions.
-- See report for snapshot, completeness and denominator limitations.
WITH frame AS (SELECT school_uid,COUNT(1) AS scheduled_n,SUM(CASE WHEN class_status=3 THEN 1 ELSE 0 END) AS opened_n,SUM(CASE WHEN class_status=4 THEN 1 ELSE 0 END) AS cancelled_n FROM eo_pdviews.ods_ms_eo_os_eeo_course_class_di_view WHERE dt>='2026-09-05' AND dt<='2026-09-11' AND class_btime>=1788537600 AND class_btime<1789142400 AND school_uid>0 GROUP BY school_uid HAVING SUM(CASE WHEN class_status=3 THEN 1 ELSE 0 END)>0), thresholds AS (SELECT percentile_approx(opened_n,0.3333333333) AS q1,percentile_approx(opened_n,0.6666666667) AS q2 FROM frame), strat AS (SELECT f.school_uid,f.scheduled_n,f.opened_n,f.cancelled_n,CASE WHEN f.opened_n<=t.q1 THEN 'low' WHEN f.opened_n<=t.q2 THEN 'mid' ELSE 'high' END AS stratum,t.q1,t.q2 FROM frame f CROSS JOIN thresholds t), period_events AS (SELECT e.school_uid,e.course_id,e.activity_id,COUNT(1) AS event_n FROM eo_pdviews.dwd_acitive_user_lms_action_details_di_view e JOIN strat f ON e.school_uid=f.school_uid WHERE e.dt>='2026-09-05' AND e.dt<='2026-09-11' AND e.event_time>=1788537600 AND e.event_time<1789142400 AND e.role='student' AND e.action IN ('handin_homework','handin_exam','looked_activity','join_discuss','handin_answer','handin_clock','en_read_aloud_submit') GROUP BY e.school_uid,e.course_id,e.activity_id),
period_activities AS (SELECT a.id,a.school_uid,a.course_id,a.category_id,a.biz_id,a.biz_type,a.start_time,a.end_time,a.student_total,a.max_score,a.is_score,a.process_flag,f.stratum,CASE WHEN a.start_time>=1788537600 AND a.start_time<1789142400 THEN 1 ELSE 0 END AS started_in_window,CASE WHEN a.end_time>=1788537600 AND a.end_time<1789142400 THEN 1 ELSE 0 END AS ended_in_window,CASE WHEN e.activity_id IS NOT NULL THEN 1 ELSE 0 END AS event_in_window FROM eo_pdviews.ods_ms_eo_oslms_lms_activity_df_view a JOIN strat f ON a.school_uid=f.school_uid LEFT JOIN period_events e ON a.school_uid=e.school_uid AND a.course_id=e.course_id AND a.id=e.activity_id WHERE a.dt='2026-09-11' AND a.is_deleted=0 AND a.publish_flag=2 AND a.biz_type=3 AND ((a.biz_type=1 AND a.start_time>=1788537600 AND a.start_time<1789142400) OR (a.biz_type<>1 AND ((a.start_time>=1788537600 AND a.start_time<1789142400) OR (a.end_time>=1788537600 AND a.end_time<1789142400) OR e.activity_id IS NOT NULL)))) SELECT biz_type,COUNT(1) AS activity_n,COUNT(DISTINCT id) AS distinct_activity_n,COUNT(DISTINCT school_uid) AS institution_n,COUNT(DISTINCT concat(CAST(school_uid AS STRING),':',CAST(course_id AS STRING),':',CAST(category_id AS STRING))) AS course_n,SUM(started_in_window) AS started_n,SUM(ended_in_window) AS ended_n,SUM(CASE WHEN started_in_window=0 AND ended_in_window=0 AND event_in_window=1 THEN 1 ELSE 0 END) AS event_only_n,SUM(CASE WHEN end_time=0 THEN 1 ELSE 0 END) AS no_end_n FROM period_activities GROUP BY biz_type ORDER BY biz_type LIMIT 30;
